  if(cap===null||cap<0||cap>1e12){if(fb)fb.textContent='Escribe lo que tienes ahora, con un número (por ejemplo, 350.000).';$('plan-actual')?.focus();return true;}
  if(mins===null||mins<0||mins>1e5){if(fb)fb.textContent='Escribe el tiempo jugado en minutos (por ejemplo, 60).';$('plan-actual-minutes')?.focus();return true;}
  let unitsNow=null;if(g.kind==='unlock'){const v=parse($('plan-actual-units')?.value);if(v!==null){if(v<0||v>1e12){if(fb)fb.textContent='Escribe tus '+g.unitLabel+' con un número.';$('plan-actual-units')?.focus();return true;}unitsNow=v;}}
  const runs={};document.querySelectorAll('[data-b-plan-actual-runs]').forEach(el=>{const v=parse(el.value);if(v!==null&&v>=0)runs[el.dataset.bPlanActualRuns]=Math.round(v);});
  const bought=[...document.querySelectorAll('[data-b-plan-actual-bought]:checked')].map(el=>el.dataset.bPlanActualBought).filter(id=>p.prerequisites.some(a=>a.id===id));
