  const logId=B.planLogId({prev:p.situation.capital,cap,mins,runs,bought,units:unitsNow,count:p.log.length?p.log[p.log.length-1].id||p.log.length:0});
  if(p.log.some(e=>e.id===logId)){if(fb)fb.textContent='Esta partida ya está guardada: nada se cuenta dos veces.';return true;}
  const before=B.evaluate('plan',s),curve=before.valid?B.planCurve(before):[],next=B.planNextSession(before),played=mins/* lot 4 : le plan repart de l’argent écrit à chaque mise à jour : la prévision de cette partie se lit à « mins » du plan d’avant, pas au temps joué depuis le début (dérive à partir de la 2e mise à jour) */;
