  const ranged=[];if(bought.length&&global.LKCarnets){try{const K=global.LKCarnets.create({storage:global.localStorage});bought.forEach(id=>{const a=p.prerequisites.find(x=>x.id===id),item=a&&a.itemId?itemFor({itemId:a.itemId}):null,fam=item?({vehicle:'vehicules',weapon:'armes'})[item.type]:null;if(!fam||!/^[a-z0-9][a-z0-9-]{0,99}$/.test(item.id))return;const r=K.applyEvent('plan:'+logId+':'+id,[{type:'own',famille:fam,id:item.id}]);if(r&&r.applied)ranged.push(item.name+(fam==='armes'?' (Mi arsenal)':' (Mi garaje)'));});}catch(e){/* stockage indisponible : le plan reste juste, rien n’est annoncé */}}
